compteur = {}

with open("auth.log") as fichier:
    for ligne in fichier:
        if "Failed password" in ligne:
            mots = ligne.split()
            ip = mots[mots.index("from") + 1]
            compteur[ip] = compteur.get(ip, 0) + 1

for ip, nombre in sorted(compteur.items(), key=lambda x: x[1], reverse=True):
    print(ip, nombre)
